package com.example.lms.controller;
import com.example.lms.dto.*; import com.example.lms.service.BorrowRecordService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.List;
@RestController @RequestMapping("/api/borrow-records") public class BorrowRecordController {private final BorrowRecordService service;public BorrowRecordController(BorrowRecordService s){service=s;}@GetMapping public List<BorrowRecordResponse> list(@RequestParam(required=false) String status){return service.list(status);}@PostMapping public ResponseEntity<BorrowRecordResponse> borrow(@Valid @RequestBody BorrowRequest r){var created=service.borrow(r);return ResponseEntity.created(URI.create("/api/borrow-records/"+created.id())).body(created);}@PostMapping("/{id}/return") @ResponseStatus(HttpStatus.NO_CONTENT) public void returnBook(@PathVariable Long id){service.returnBook(id);}}
